def transform(grid):
    from collections import Counter

    # Get background color
    colors = Counter()
    for row in grid:
        colors.update(row)
    bg_color = colors.most_common(1)[0][0]

    rows, cols = len(grid), len(grid[0])

    # Divide into 3x3 regions
    rx = rows // 3
    cy = cols // 3

    output = [[0 for _ in range(3)] for _ in range(3)]

    for i in range(3):
        for j in range(3):
            # Regular division, adjust for remainder
            r1, r2 = i * rx, min((i+1) * rx, rows)
            c1, c2 = j * cy, min((j+1) * cy, cols)

            # Count non-background in full coverage
            count = 0
            for r in range(r1, r2):
                for c in range(c1, c2):
                    if grid[r][c] != bg_color:
                        count += 1

            # Output 5 based on "contentful" regions
            if count > 0:
                output[i][j] = 5
            else:
                output[i][j] = 0

    return output
